using System;using System.Collections.Generic;using UnityEngine;
[Serializable]public class DiagramSpec{public string kind,page_resource,page_sha256,cutout_resource,cutout_sha256;public float width,height,page_width;public float[] crop,centroid;}
public struct ThinLensResult{public bool infinity;public double distance,imageDistance,magnification;}
public class SourceDiagramPhysics:MonoBehaviour{
 public DiagramSpec spec;public double objectX=350,focal=124,voltage=100,r1=300,r2=200,angle,velocity,initialAngle,length=1,damping=.02,time;public bool playing,compare;public int stage;public TextMesh label;
 GameObject overlay,reference;Transform objectSprite,imageSprite,bob;LineRenderer ray1,ray2,rope,trace;readonly List<Transform> charges=new List<Transform>();readonly List<Vector3> history=new List<Vector3>();readonly List<Mesh> meshes=new List<Mesh>();readonly List<Material> materials=new List<Material>();
 public static ThinLensResult Lens(double x,double f){double d=653-x;bool infinity=d<=0||Math.Abs(d-f)<.01;double v=infinity?0:f*d/(d-f);return new ThinLensResult{infinity=infinity,distance=d,imageDistance=v,magnification=infinity?0:-v/d};}
 public double Current=>voltage/(r1+r2);public double Energy=>.5*length*length*velocity*velocity+9.81*length*(1-Math.Cos(angle));
 public Vector3 Pixel(double x,double y,double z=-.003){return new Vector3((float)((x/spec.width-.5)*spec.page_width),(float)((spec.height*.5-y)*spec.page_width/spec.width),(float)z);}
 public Vector2 BobPixel{get{double dx=spec.centroid[0]-259,dy=spec.centroid[1]-61,lp=Math.Sqrt(dx*dx+dy*dy);return new Vector2((float)(259+lp*Math.Sin(angle)),(float)(61+lp*Math.Cos(angle)));}}
 public void Configure(CatalogItem item){var asset=Resources.Load<TextAsset>(item.diagram_file);if(!asset)throw new Exception("Missing source physics spec");SourcePartsScene.RequireHash(asset.bytes,item.diagram_sha256);spec=JsonUtility.FromJson<DiagramSpec>(asset.text);var bytes=Resources.Load<TextAsset>(spec.page_resource+"-hashbytes");if(!bytes)throw new Exception("Missing source page bytes");SourcePartsScene.RequireHash(bytes.bytes,spec.page_sha256);reference=Quad("Immutable source reference",transform,spec.page_resource,spec.width,spec.height);reference.transform.localPosition=new Vector3(0,0,-.001f);overlay=new GameObject("Transparent authored source physics overlay");overlay.transform.SetParent(transform,false);
 if(spec.kind!="circuit"){var cut=Resources.Load<TextAsset>(spec.cutout_resource+"-hashbytes");if(!cut)throw new Exception("Missing source RGBA");SourcePartsScene.RequireHash(cut.bytes,spec.cutout_sha256);var sprite=Quad("Genuine learned original RGB "+spec.kind,overlay.transform,spec.cutout_resource,spec.crop[2],spec.crop[3]).transform;if(spec.kind=="optics"){objectSprite=sprite;imageSprite=Quad("Derived image of original tree, not new artwork",overlay.transform,spec.cutout_resource,spec.crop[2],spec.crop[3]).transform;ray1=Line("Prepared parallel/focus ray",Color.green);ray2=Line("Prepared central ray / virtual extension",Color.cyan);}else{bob=sprite;rope=Line("Numerical angle constrained rod",Color.blue);trace=Line("Actual RK4 theta history",new Color(1,.5f,0));initialAngle=Math.Atan2(spec.centroid[0]-259,spec.centroid[1]-61);}}
 else{for(int i=0;i<12;i++){var go=Quad("Authored charge marker, not electron speed",overlay.transform,null,5,5);charges.Add(go.transform);}}
 var g=new GameObject("Physics source controls and equations");g.transform.SetParent(transform,false);g.transform.localPosition=new Vector3(0,-item.height*.55f,-.004f);label=g.AddComponent<TextMesh>();label.characterSize=.0023f;label.fontSize=38;label.anchor=TextAnchor.MiddleCenter;label.alignment=TextAlignment.Center;Reset();Render();}
 GameObject Quad(string name,Transform parent,string texture,float w,float h){var go=new GameObject(name);go.transform.SetParent(parent,false);float scale=spec.page_width/spec.width;var m=new Mesh{vertices=new[]{new Vector3(-w*scale/2,-h*scale/2,0),new Vector3(w*scale/2,-h*scale/2,0),new Vector3(w*scale/2,h*scale/2,0),new Vector3(-w*scale/2,h*scale/2,0)},uv=new[]{Vector2.zero,Vector2.right,Vector2.one,Vector2.up},triangles=new[]{0,2,1,0,3,2}};m.RecalculateBounds();meshes.Add(m);go.AddComponent<MeshFilter>().sharedMesh=m;var mat=new Material(Resources.Load<Shader>("CatalogSurface"));if(texture!=null){var tex=Resources.Load<Texture2D>(texture);if(!tex)throw new Exception("Missing source texture");mat.SetTexture("_BaseMap",tex);}else mat.SetColor("_BaseColor",Color.cyan);materials.Add(mat);go.AddComponent<MeshRenderer>().sharedMaterial=mat;return go;}
 LineRenderer Line(string name,Color color){var go=new GameObject(name);go.transform.SetParent(overlay.transform,false);var l=go.AddComponent<LineRenderer>();l.useWorldSpace=false;l.widthMultiplier=.00045f;l.startColor=l.endColor=color;var mat=new Material(Shader.Find("Sprites/Default"));materials.Add(mat);l.sharedMaterial=mat;return l;}
 public void Reset(){objectX=350;focal=124;voltage=100;r1=300;r2=200;length=1;angle=initialAngle;velocity=0;time=0;stage=0;playing=false;compare=false;history.Clear();}
 public void Tap(){playing=!playing;stage=(stage+1)%3;Render();}public void Compare(){compare=!compare;Render();}
 public void Axes(Vector2 left,Vector2 right,float dt){if(!float.IsFinite(dt)||!float.IsFinite(left.x)||!float.IsFinite(right.x)||!float.IsFinite(right.y)||dt<0)return;if(spec.kind=="optics"){objectX=Math.Clamp(objectX+left.x*150*dt,150,635);focal=Math.Clamp(focal+right.x*60*dt,30,220);}else if(spec.kind=="circuit"){voltage=Math.Clamp(voltage+left.x*60*dt,0,200);r1=Math.Clamp(r1+right.x*300*dt,1,1000);r2=Math.Clamp(r2+right.y*300*dt,1,1000);}else{length=Math.Clamp(length+left.x*dt,.2,3);if(Math.Abs(right.x)>.01){initialAngle=Math.Clamp(initialAngle*180/Math.PI+right.x*35*dt,-85,85)*Math.PI/180;angle=initialAngle;velocity=0;history.Clear();}}Render();}
 public void Advance(double interval){if(double.IsNaN(interval)||double.IsInfinity(interval)||interval<=0)return;double duration=Math.Min(interval,.1);int n=Math.Max(1,(int)Math.Ceiling(duration/.002));double dt=duration/n;for(int i=0;i<n;i++){double a=angle,v=velocity;double k1a=v,k1v=Acceleration(a,v),k2a=v+dt*k1v/2,k2v=Acceleration(a+dt*k1a/2,v+dt*k1v/2),k3a=v+dt*k2v/2,k3v=Acceleration(a+dt*k2a/2,v+dt*k2v/2),k4a=v+dt*k3v,k4v=Acceleration(a+dt*k3a,v+dt*k3v);angle+=dt*(k1a+2*k2a+2*k3a+k4a)/6;velocity+=dt*(k1v+2*k2v+2*k3v+k4v)/6;time+=dt;}}
 double Acceleration(double a,double v)=>-9.81/length*Math.Sin(a)-damping*v;
 void SpriteAt(Transform t,double anchorX,double anchorY,double sourceAnchorX,double sourceAnchorY,float sx=1,float sy=1){double ox=spec.crop[0]+spec.crop[2]/2-sourceAnchorX,oy=spec.crop[1]+spec.crop[3]/2-sourceAnchorY;t.localPosition=Pixel(anchorX+ox*sx,anchorY+oy*sy);t.localScale=new Vector3(sx,sy,1);}
 public void Render(){reference.SetActive(compare);overlay.SetActive(!compare);string equation;
 if(spec.kind=="optics"){var s=Lens(objectX,focal);SpriteAt(objectSprite,objectX,567,350,567);imageSprite.gameObject.SetActive(stage>0&&!s.infinity&&Math.Abs(s.magnification)<10);if(imageSprite.gameObject.activeSelf)SpriteAt(imageSprite,653+s.imageDistance,567,350,567,(float)Math.Abs(s.magnification),(float)s.magnification);ray1.positionCount=stage==2?3:0;ray2.positionCount=stage==2?3:0;if(stage==2){ray1.SetPositions(new[]{Pixel(objectX,487),Pixel(653,487),Pixel(1000,487+347*80/focal)});ray2.SetPositions(new[]{Pixel(objectX,487),Pixel(653,567),Pixel(1000,567+347*80/(653-objectX))});}equation=s.infinity?"Object at focus: image at infinity (finite image hidden)":"f="+focal.ToString("F1")+" px · d="+s.distance.ToString("F1")+" · v="+s.imageDistance.ToString("F1")+" · m="+s.magnification.ToString("F2")+(s.magnification>0?" virtual upright":" real inverted");}
 else if(spec.kind=="circuit"){Vector2[] path={new Vector2(147,388),new Vector2(147,294),new Vector2(475,294),new Vector2(475,388),new Vector2(147,388)};float[] lengths={94,328,94,328};for(int i=0;i<charges.Count;i++){charges[i].gameObject.SetActive(stage>0);double d=(time*Current*100+i*844.0/12)%844;for(int j=0;j<4;j++){if(d<=lengths[j]){var p=Vector2.Lerp(path[j],path[j+1],(float)(d/lengths[j]));charges[i].localPosition=Pixel(p.x,p.y);break;}d-=lengths[j];}}equation=voltage.ToString("F1")+" V / ("+r1.ToString("F0")+" + "+r2.ToString("F0")+" Ω) = "+Current.ToString("F3")+" A\nDrops "+(Current*r1).ToString("F1")+" + "+(Current*r2).ToString("F1")+" V; authored markers, not electron speed";}
 else{var p=BobPixel;SpriteAt(bob,p.x,p.y,spec.centroid[0],spec.centroid[1]);rope.positionCount=2;rope.SetPositions(new[]{Pixel(259,61),Pixel(p.x,p.y)});trace.positionCount=stage==2?history.Count:0;if(stage==2)trace.SetPositions(history.ToArray());equation="θ="+(angle*180/Math.PI).ToString("F1")+"° · L="+length.ToString("F2")+" m · RK4 energy/m="+Energy.ToString("F3");}
 label.text="Original "+spec.kind+" · stage "+stage+" · "+(compare?"immutable source comparison":"transparent authored overlay")+"\nA: stage/play · B: reset · L-click: source compare · X/Y: scene\n"+(spec.kind=="optics"?"L-stick object · R-stick focal":spec.kind=="circuit"?"L-stick voltage · R X/Y resistance1/2":"L-stick length · R-stick signed launch angle")+"\n"+equation+"\nPrepared fixture only; no OCR/general MNA/calibration";
 }
 void Update(){if(playing){double dt=Math.Min(Time.deltaTime,.05);if(spec.kind=="pendulum"){Advance(dt);history.Add(new Vector3((float)(-.09+(time%6)*.015),.025f+(float)angle*.02f,-.004f));if(history.Count>360)history.RemoveAt(0);}else time+=dt;}Render();}
 void OnDestroy(){foreach(var m in meshes)if(m){if(Application.isPlaying)Destroy(m);else DestroyImmediate(m);}foreach(var m in materials)if(m){if(Application.isPlaying)Destroy(m);else DestroyImmediate(m);}}
}
